<script setup lang="ts">
import { ref } from 'vue';
import type { ChartType } from '../types';
import type { ChartSettings, LegendPosition, NumberFormat, ThemeName } from '../state/project';
import { palettes } from '../charts/config';
import SeriesEditor from './SeriesEditor.vue';
import AxisStyleEditor from './AxisStyleEditor.vue';
const props=defineProps<{settings:ChartSettings;numericColumns:number;headers:string[]}>();
const emit=defineEmits<{change:[value:Partial<ChartSettings>]} >();
const tab=ref<'chart'|'style'|'text'>('chart');
const types:{value:ChartType;label:string;min:number}[]=[{value:'bar',label:'柱状',min:1},{value:'line',label:'折线',min:1},{value:'area',label:'面积',min:1},{value:'combo',label:'组合',min:2},{value:'pie',label:'饼图',min:1},{value:'doughnut',label:'环形',min:1},{value:'radar',label:'雷达',min:1},{value:'scatter',label:'散点',min:2},{value:'bubble',label:'气泡',min:3},{value:'waterfall',label:'瀑布',min:1},{value:'heatmap',label:'热力',min:2},{value:'funnel',label:'漏斗',min:1}];
const themes=Object.keys(palettes) as ThemeName[];
const legends:{value:LegendPosition;label:string}[]=[{value:'top',label:'顶部'},{value:'bottom',label:'底部'},{value:'left',label:'左侧'},{value:'right',label:'右侧'}];
const formats:{value:NumberFormat;label:string}[]=[{value:'number',label:'数字'},{value:'compact',label:'紧凑'},{value:'percent',label:'百分比'},{value:'currency',label:'人民币'}];
function updateCustomColor(index:number,color:string){const colors=[...props.settings.customColors];while(colors.length<=index)colors.push(palettes[props.settings.theme].colors[colors.length%palettes[props.settings.theme].colors.length]);colors[index]=color;emit('change',{customColors:colors});}
function resetCustomColors(){emit('change',{customColors:[]});}
function optionalNumber(value:string){return value.trim()===''?null:Number(value);}
function exportBrand(){const contents=JSON.stringify({version:1,theme:props.settings.theme,customColors:props.settings.customColors,background:props.settings.background,numberFormat:props.settings.numberFormat,valuePrefix:props.settings.valuePrefix,valueSuffix:props.settings.valueSuffix},null,2);const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([contents],{type:'application/json'}));link.download='chart-brand-theme.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}
function importBrand(){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{const value=JSON.parse(await file.text());const colors=Array.isArray(value.customColors)?value.customColors.filter((color:unknown)=>typeof color==='string'&&/^#[0-9a-f]{6}$/i.test(color)).slice(0,12):[];emit('change',{theme:themes.includes(value.theme)?value.theme:props.settings.theme,customColors:colors,background:typeof value.background==='string'&&/^#[0-9a-f]{6}$/i.test(value.background)?value.background:props.settings.background,numberFormat:formats.some(item=>item.value===value.numberFormat)?value.numberFormat:props.settings.numberFormat,valuePrefix:String(value.valuePrefix??'').slice(0,20),valueSuffix:String(value.valueSuffix??'').slice(0,20)});}catch{alert('品牌主题文件无效');}};input.click();}
</script>
<template><aside class="property-panel panel-shell"><div class="panel-heading"><div><span class="eyebrow">DESIGN</span><h2>属性</h2></div></div><div class="property-tabs"><button :class="{active:tab==='chart'}" @click="tab='chart'">图表</button><button :class="{active:tab==='style'}" @click="tab='style'">样式</button><button :class="{active:tab==='text'}" @click="tab='text'">文字</button></div>
<template v-if="tab==='chart'"><section class="property-section"><label>图表类型</label><div class="type-grid"><button v-for="item in types" :key="item.value" :disabled="numericColumns<item.min" :class="{active:settings.type===item.value}" @click="emit('change',{type:item.value})">{{item.label}}</button></div></section><SeriesEditor v-if="['bar','line','area'].includes(settings.type)" :settings="settings" :headers="headers" :combo="false" @change="emit('change',$event)"/><section v-if="settings.type==='bar'" class="property-section toggles"><label><span>横向柱状</span><input type="checkbox" :checked="settings.horizontal" @change="emit('change',{horizontal:($event.target as HTMLInputElement).checked})"></label><label><span>数据堆叠</span><input type="checkbox" :checked="settings.stacked" @change="emit('change',{stacked:($event.target as HTMLInputElement).checked})"></label><label><span>百分比堆叠</span><input type="checkbox" :checked="settings.percentageStacked" @change="emit('change',{percentageStacked:($event.target as HTMLInputElement).checked,stacked:($event.target as HTMLInputElement).checked||settings.stacked})"></label></section><section v-if="settings.type==='bar'||settings.type==='combo'" class="property-section"><label>柱间距 {{Math.round((1-settings.barCategoryPercentage)*100)}}%</label><input class="range-field" type="range" min="5" max="70" step="5" :value="Math.round((1-settings.barCategoryPercentage)*100)" @input="emit('change',{barCategoryPercentage:1-Number(($event.target as HTMLInputElement).value)/100})"><label>组内柱宽 {{Math.round(settings.barPercentage*100)}}%</label><input class="range-field" type="range" min="40" max="100" step="5" :value="settings.barPercentage*100" @input="emit('change',{barPercentage:Number(($event.target as HTMLInputElement).value)/100})"><label>柱角半径 {{settings.barRadius}}</label><input class="range-field" type="range" min="0" max="16" step="1" :value="settings.barRadius" @input="emit('change',{barRadius:Number(($event.target as HTMLInputElement).value)})"><label>柱边框 {{settings.barBorderWidth}}px</label><input class="range-field" type="range" min="0" max="4" step="1" :value="settings.barBorderWidth" @input="emit('change',{barBorderWidth:Number(($event.target as HTMLInputElement).value)})"></section><section v-if="settings.type==='line'||settings.type==='area'||settings.type==='combo'" class="property-section toggles"><label><span>平滑曲线</span><input type="checkbox" :checked="settings.smooth" @change="emit('change',{smooth:($event.target as HTMLInputElement).checked})"></label><label><span>面积填充</span><input type="checkbox" :checked="settings.areaFill" @change="emit('change',{areaFill:($event.target as HTMLInputElement).checked})"></label><label><span>连接缺失值</span><input type="checkbox" :checked="settings.connectGaps" @change="emit('change',{connectGaps:($event.target as HTMLInputElement).checked})"></label></section><section v-if="settings.type==='line'||settings.type==='area'||settings.type==='combo'" class="property-section"><label>线宽 {{settings.lineWidth}}px</label><input class="range-field" type="range" min="1" max="6" step="1" :value="settings.lineWidth" @input="emit('change',{lineWidth:Number(($event.target as HTMLInputElement).value)})"><label>数据点 {{settings.pointRadius}}px</label><input class="range-field" type="range" min="0" max="8" step="1" :value="settings.pointRadius" @input="emit('change',{pointRadius:Number(($event.target as HTMLInputElement).value)})"><label class="axis-zero"><span>虚线</span><input type="checkbox" :checked="settings.lineDash" @change="emit('change',{lineDash:($event.target as HTMLInputElement).checked})"></label><label class="axis-zero"><span>阶梯线</span><input type="checkbox" :checked="settings.lineStepped" @change="emit('change',{lineStepped:($event.target as HTMLInputElement).checked})"></label></section><section v-if="settings.type==='scatter'" class="property-section toggles"><label><span>趋势线与 R²</span><input type="checkbox" :checked="settings.showTrendline" @change="emit('change',{showTrendline:($event.target as HTMLInputElement).checked})"></label></section><SeriesEditor v-if="settings.type==='combo'" :settings="settings" :headers="headers" :combo="true" @change="emit('change',$event)"/><section v-if="settings.type==='combo'" class="property-section combo-axis"><label class="axis-zero"><span>右轴从 0 开始</span><input type="checkbox" :checked="settings.y2BeginAtZero" @change="emit('change',{y2BeginAtZero:($event.target as HTMLInputElement).checked})"></label><label>右轴标题<input class="field" :value="settings.rightAxisTitle" placeholder="例如 完成率" @input="emit('change',{rightAxisTitle:($event.target as HTMLInputElement).value})"></label><label>右轴格式<select class="field" :value="settings.rightAxisFormat" @change="emit('change',{rightAxisFormat:($event.target as HTMLSelectElement).value as NumberFormat|'auto'})"><option value="auto">自动识别</option><option v-for="item in formats" :key="item.value" :value="item.value">{{item.label}}</option></select></label><div class="axis-range"><label>右轴最小<input class="field" type="number" :value="settings.y2Min??''" @input="emit('change',{y2Min:optionalNumber(($event.target as HTMLInputElement).value)})"></label><label>右轴最大<input class="field" type="number" :value="settings.y2Max??''" @input="emit('change',{y2Max:optionalNumber(($event.target as HTMLInputElement).value)})"></label><label>右轴步长<input class="field" type="number" min="0" :value="settings.y2Step??''" @input="emit('change',{y2Step:optionalNumber(($event.target as HTMLInputElement).value)})"></label></div></section><section v-if="settings.type==='pie'||settings.type==='doughnut'" class="property-section"><label>起始角度 {{settings.pieRotation}}°</label><input class="range-field" type="range" min="-180" max="180" step="15" :value="settings.pieRotation" @input="emit('change',{pieRotation:Number(($event.target as HTMLInputElement).value)})"><template v-if="settings.type==='doughnut'"><label>中心孔 {{settings.pieCutout}}%</label><input class="range-field" type="range" min="30" max="80" step="5" :value="settings.pieCutout" @input="emit('change',{pieCutout:Number(($event.target as HTMLInputElement).value)})"><label>中心文案<input class="field" :value="settings.pieCenterText" placeholder="例如 总计" @input="emit('change',{pieCenterText:($event.target as HTMLInputElement).value})"></label></template><label>合并小于 {{settings.pieMergeSmallThreshold}}% 的项目</label><input class="range-field" type="range" min="0" max="15" step="1" :value="settings.pieMergeSmallThreshold" @input="emit('change',{pieMergeSmallThreshold:Number(($event.target as HTMLInputElement).value)})"></section><section class="property-section"><label>图例位置</label><select class="field" :value="settings.legendPosition" @change="emit('change',{legendPosition:($event.target as HTMLSelectElement).value as LegendPosition})"><option v-for="item in legends" :key="item.value" :value="item.value">{{item.label}}</option></select></section><section class="property-section"><label>X 轴标签角度 {{settings.xLabelRotation}}°</label><input class="range-field" type="range" min="0" max="90" step="15" :value="settings.xLabelRotation" @input="emit('change',{xLabelRotation:Number(($event.target as HTMLInputElement).value)})"><label>最多显示 {{settings.xMaxTicks}} 个 X 轴刻度</label><input class="range-field" type="range" min="3" max="30" step="1" :value="settings.xMaxTicks" @input="emit('change',{xMaxTicks:Number(($event.target as HTMLInputElement).value)})"><label>网格线 {{settings.gridLineWidth}}px</label><input class="range-field" type="range" min="0.5" max="3" step="0.5" :value="settings.gridLineWidth" @input="emit('change',{gridLineWidth:Number(($event.target as HTMLInputElement).value)})"><label class="axis-zero"><span>显示坐标轴边线</span><input type="checkbox" :checked="settings.showAxisBorder" @change="emit('change',{showAxisBorder:($event.target as HTMLInputElement).checked})"></label><label v-if="settings.showDataLabels">数据标签位置<select class="field" :value="settings.dataLabelPosition" @change="emit('change',{dataLabelPosition:($event.target as HTMLSelectElement).value as 'auto'|'top'|'center'})"><option value="auto">自动</option><option value="top">顶部</option><option value="center">居中</option></select></label></section><AxisStyleEditor :settings="settings" @change="emit('change',$event)"/><section class="property-section toggles"><label><span>显示图例</span><input type="checkbox" :checked="settings.showLegend" @change="emit('change',{showLegend:($event.target as HTMLInputElement).checked})"></label><label><span>显示数据标签</span><input type="checkbox" :checked="settings.showDataLabels" @change="emit('change',{showDataLabels:($event.target as HTMLInputElement).checked})"></label><label><span>显示网格线</span><input type="checkbox" :checked="settings.showGrid" @change="emit('change',{showGrid:($event.target as HTMLInputElement).checked})"></label><label><span>图表动画</span><input type="checkbox" :checked="settings.animate" @change="emit('change',{animate:($event.target as HTMLInputElement).checked})"></label></section></template>
<template v-else-if="tab==='style'"><section class="property-section"><label>专业配色</label><div class="palette-grid"><button v-for="theme in themes" :key="theme" :class="{active:settings.theme===theme}" :title="theme" @click="emit('change',{theme})"><i v-for="color in palettes[theme].colors.slice(0,4)" :key="color" :style="{background:color}"></i></button></div></section><section class="property-section"><label>品牌色</label><div class="brand-colors"><input v-for="index in 5" :key="index" type="color" :value="settings.customColors[index-1]||palettes[settings.theme].colors[index-1]" @input="updateCustomColor(index-1,($event.target as HTMLInputElement).value)"><button v-if="settings.customColors.length" @click="resetCustomColors">重置</button></div><label class="background-color">画布背景<input type="color" :value="settings.background||palettes[settings.theme].background" @input="emit('change',{background:($event.target as HTMLInputElement).value})"><button v-if="settings.background" @click="emit('change',{background:''})">跟随主题</button></label><div class="brand-actions"><button @click="importBrand">导入主题</button><button @click="exportBrand">导出主题</button></div></section><section class="property-section"><label>数字格式</label><select class="field" :value="settings.numberFormat" @change="emit('change',{numberFormat:($event.target as HTMLSelectElement).value as NumberFormat})"><option v-for="item in formats" :key="item.value" :value="item.value">{{item.label}}</option></select></section><section class="property-section"><label>小数位 {{settings.decimals}}</label><input class="range-field" type="range" min="0" max="3" step="1" :value="settings.decimals" @input="emit('change',{decimals:Number(($event.target as HTMLInputElement).value)})"></section><section class="property-section field-stack"><label>数值前缀<input class="field" :value="settings.valuePrefix" placeholder="例如 ¥" @input="emit('change',{valuePrefix:($event.target as HTMLInputElement).value})"></label><label>数值后缀<input class="field" :value="settings.valueSuffix" placeholder="例如 万元" @input="emit('change',{valueSuffix:($event.target as HTMLInputElement).value})"></label></section></template><template v-else><section class="property-section field-stack"><label>主标题<input class="field" :value="settings.title" @input="emit('change',{title:($event.target as HTMLInputElement).value})"></label><label>副标题<input class="field" :value="settings.subtitle" placeholder="可选" @input="emit('change',{subtitle:($event.target as HTMLInputElement).value})"></label><label>X 轴标题<input class="field" :value="settings.xAxisTitle" placeholder="可选" @input="emit('change',{xAxisTitle:($event.target as HTMLInputElement).value})"></label><label>Y 轴标题<input class="field" :value="settings.yAxisTitle" placeholder="可选" @input="emit('change',{yAxisTitle:($event.target as HTMLInputElement).value})"></label><label class="axis-zero"><span>左轴从 0 开始</span><input type="checkbox" :checked="settings.yBeginAtZero" @change="emit('change',{yBeginAtZero:($event.target as HTMLInputElement).checked})"></label><div class="axis-range"><label>最小值<input class="field" type="number" :value="settings.yMin??''" @input="emit('change',{yMin:optionalNumber(($event.target as HTMLInputElement).value)})"></label><label>最大值<input class="field" type="number" :value="settings.yMax??''" @input="emit('change',{yMax:optionalNumber(($event.target as HTMLInputElement).value)})"></label><label>步长<input class="field" type="number" min="0" :value="settings.yStep??''" @input="emit('change',{yStep:optionalNumber(($event.target as HTMLInputElement).value)})"></label></div><label>数据来源<input class="field" :value="settings.source" placeholder="例如：内部经营数据" @input="emit('change',{source:($event.target as HTMLInputElement).value})"></label></section></template></aside></template>
